```python
import json

def process_table(table_code, target_cells):
    # Parse table headers
    headers = table_code.splitlines()[0].split()
    headers = headers[:-1]  # exclude the last header which is the column name

    # Determine record type for each cell
    record_types = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        if headers[j-1].startswith('Glass'):
            if 'mol%' in table_code or 'mol' in table_code or 'wt%' in table_code or 'wt' in table_code:
                record_types.append('Glass_Compound_Amount')
            else:
                record_types.append('Other')
        else:
            record_types.append('Other')

    # Create JSON response
    response = {
        "cell_index": [[i, j, k] for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k'])],
        "cell_record": []
    }

    for i, j, k, value, record_type in zip(target_cells['i'], target_cells['j'], target_cells['k'], target_cells['cell_value_processed'], record_types):
        if record_type == 'Glass_Compound_Amount':
            # Determine constituent, unit, and material
            if 'Bi2O3' in table_code:
                constituent = 'Bi2O3'
                unit = 'mol'
                if 'wt%' in table_code:
                    unit = 'wt'
            elif 'B2O3' in table_code:
                constituent = 'B2O3'
                unit = 'mol'
                if 'wt%' in table_code:
                    unit = 'wt'
            elif 'BaO' in table_code:
                constituent = 'BaO'
                unit = 'mol'
                if 'wt%' in table_code:
                    unit = 'wt'
            elif 'ZnO' in table_code:
                constituent = 'ZnO'
                unit = 'mol'
                if 'wt%' in table_code:
                    unit = 'wt'
            elif 'CuO' in table_code:
                constituent = 'CuO'
                unit = 'mol'
                if 'wt%' in table_code:
                    unit = 'wt'
            elif 'SiO2' in table_code:
                constituent = 'SiO2'
                unit = 'mol'
                if 'wt%' in table_code:
                    unit = 'wt'
            elif 'CaO' in table_code:
                constituent = 'CaO'
                unit = 'mol'
                if 'wt%' in table_code:
                    unit = 'wt'
            elif 'MgO' in table_code:
                constituent = 'MgO'
                unit = 'mol'
                if 'wt%' in table_code:
                    unit = 'wt'
            elif 'Al2O3' in table_code:
                constituent = 'Al2O3'
                unit = 'mol'
                if 'wt%' in table_code:
                    unit = 'wt'
            elif 'Tg' in table_code:
                constituent = 'Tg'
                unit = 'degC'
            elif 'Tx' in table_code:
                constituent = 'Tx'
                unit = 'degC'
            elif 'DT' in table_code:
                constituent = 'DT'
                unit = 'degC'
            elif 'n' in table_code:
                constituent = 'n'
                unit = ''
            else:
                constituent = headers[j-1]
                unit = ''

            # Determine material
            if 'Sample' in table_code:
                material = headers[i-1]
            elif 'No.' in table_code:
                material = headers[i-1]
            else:
                material = 'xx'

            # Create record
            record = {
                "value": value,
                "type": record_type,
                "constituent": constituent,
                "unit": unit,
                "material": material
            }
        else:
            record = {
                "value": value,
                "type": record_type
            }

        # Add record to response
        response['cell_record'].append(json.dumps(record))

    return json.dumps(response)

# Example usage
