import json

# Define the table data
table = {
    "Isotope": ["119Sn", "125Te", "129I"],
    "Eg (keV)": ["23.87", "35.46", "27.77"],
    "G (mm/s)": ["0.647", "5.208", "0.586"],
    "Source material": ["Ba 119m  SnO 3", "Mg  125m  TeO 6", "Zn  129m  Te"],
    "Half life of precursor": ["245 days", "57 days", "33 days"],
    "b (%)": ["8.58", "6.99", "Artificial"]
}

# Define the target cells
target_cells = {
    'cell_value_processed': ['23.87', '0.647', '8.58', '35.46', '5.208', '6.99', '27.77', '0.586'],
    'i': [1, 1, 1, 2, 2, 2, 3, 3],
    'j': [1, 2, 5, 1, 2, 5, 1, 2],
    'k': [0, 0, 0, 0, 0, 0, 0, 0]
}

# Define the column headers
column_headers = list(table.keys())

# Define the record types
record_types = {
    "Glass_Compound_Amount": ["Glass_Compound_Amount"],
    "Other": ["Isotope", "Eg (keV)", "G (mm/s)", "Source material", "Half life of precursor", "b (%)"]
}

# Create the cell records
cell_records = []
for i, value in enumerate(target_cells['cell_value_processed']):
    cell_index = [target_cells['i'][i], target_cells['j'][i], target_cells['k'][i]]
    if column_headers[target_cells['i'][i] - 1] in record_types["Glass_Compound_Amount"]:
        if column_headers[target_cells['i'][i] - 1] == "b (%)":
            if value == "Artificial":
                value = "0"
        record = {
            "value": value,
            "type": "Glass_Compound_Amount",
            "constituent": column_headers[target_cells['j'][i] - 1],
            "unit": "mol" if column_headers[target_cells['j'][i] - 1] == "b (%)" else "wt",
            "material": "xx"
        }
    else:
        record = {
            "value": value,
            "type": "Other"
        }
    cell_records.append(json.dumps(record))

# Create the output dictionary
output = {
    "cell_index": [[target_cells['i'][i], target_cells['j'][i], target_cells['k'][i]] for i in range(len(target_cells['cell_value_processed'])]),
    "cell_record": cell_records
}

# Verify the output
assert len(output["cell_index"]) == len(target_cells['cell_value_processed'])
assert len(output["cell_record"]) == len(target_cells['cell_value_processed'])
for i in range(len(output["cell_index"])):
    assert output["cell_index"][i] == [target_cells['i'][i], target_cells['j'][i], target_cells['k'][i]]
    assert output["cell_record"][i] == json.dumps({
        "value": target_cells['cell_value_processed'][i],
        "type": "Glass_Compound_Amount" if column_headers[target_cells['i'][i] - 1] in record_types["Glass_Compound_Amount"] else "Other"
    })

# Print the output
print(json.dumps(output, indent=4))
