import json

def process_table(table_code, target_cells):
    # Extract table headers
    headers = [cell.strip() for cell in table_code.splitlines()[0].split("|")[1:]]

    # Determine record type for each cell
    record_types = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        if headers[j] in ['Sample no.', 'Sample', 'No.']:
            record_types.append('Other')
        elif headers[j] in ['T g', 'T c1', 'T c2', 'T c3', 'T m1', 'T m2']:
            record_types.append('Glass_Compound_Amount')
        else:
            record_types.append('Other')

    # Create cell records
    cell_records = []
    for i, j, k, record_type, value in zip(target_cells['i'], target_cells['j'], target_cells['k'], record_types, target_cells['cell_value_processed']):
        if record_type == 'Glass_Compound_Amount':
            if headers[j] in ['T g', 'T c1', 'T c2', 'T c3', 'T m1', 'T m2']:
                if headers[j] in ['T g', 'T c1', 'T c2', 'T c3', 'T m1', 'T m2']:
                    if headers[j] in ['T g', 'T c1', 'T c2', 'T c3']:
                        unit = 'degC'
                    else:
                        unit = 'degC'
                    if headers[j] in ['T g', 'T c1', 'T c2', 'T c3', 'T m1']:
                        material = 'xx'
                    else:
                        material = 'xx'
                constituent = headers[j].replace(' ', '')
                cell_record = json.dumps({'value': value, 'type': 'Glass_Compound_Amount', 'constituent': constituent, 'unit': unit, 'material': material})
            else:
                constituent = headers[j].replace(' ', '')
                if 'mol%' in value:
                    unit = 'mol'
                elif 'wt%' in value:
                    unit = 'wt'
                else:
                    unit = 'xx'
                if headers[0] in ['Sample no.', 'Sample', 'No.']:
                    material = headers[0].replace(' ', '')
                else:
                    material = 'xx'
                cell_record = json.dumps({'value': value, 'type': 'Glass_Compound_Amount', 'constituent': constituent, 'unit': unit, 'material': material})
        else:
            cell_record = json.dumps({'value': value, 'type': 'Other'})

        cell_records.append(cell_record)

    # Create output dictionary
    output = {
        'cell_index': list(zip(target_cells['i'], target_cells['j'], target_cells['k'])),
        'cell_record': cell_records
    }

    return json.dumps(output)

# Example usage
